<?php
require_once __DIR__.'/includes/db.php';$q=trim($_GET['q']??'');$cat=trim($_GET['category']??'');$sql="SELECT * FROM apps WHERE status='published'";$p=[];if($q!==''){$sql.=" AND (name LIKE ? OR description LIKE ?)";$p[]="%$q%";$p[]="%$q%";}if($cat!==''){$sql.=" AND category=?";$p[]=$cat;}$sql.=" ORDER BY created_at DESC";$s=db()->prepare($sql);$s->execute($p);$apps=$s->fetchAll();$cats=db()->query("SELECT DISTINCT category FROM apps WHERE status='published'")->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Kho ứng dụng';require __DIR__.'/includes/header.php';?><section class="hero"><small>HENDY DIGITAL</small><h1>Khám phá ứng dụng<br>và trò chơi</h1><p>Kho ứng dụng dành cho cộng đồng Hendy.</p><a class="btn" href="dichvumang.php">Dịch vụ mạng</a></section><div class="heading"><h2>Ứng dụng & trò chơi (<?=count($apps)?>)</h2><form><input type="hidden" name="q" value="<?=e($q)?>"><select name="category" onchange="this.form.submit()"><option value="">Tất cả danh mục</option><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=$cat===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></form></div><div class="cards"><?php foreach($apps as $a):?><article class="card"><div class="appicon"><?=e(mb_substr($a['name'],0,1))?></div><small><?=e($a['category'])?></small><h3><?=e($a['name'])?></h3><p><?=e(mb_strimwidth($a['description'],0,100,'…'))?></p><a href="detail.php?id=<?=(int)$a['id']?>">Chi tiết →</a></article><?php endforeach;?></div><?php if(!$apps):?><p class="empty">Chưa có ứng dụng phù hợp.</p><?php endif;?></main></body></html>